    end

    // Bridge ID for read channel (constant - tied to BRIDGE_ID parameter)
    assign bridge_id_ar = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Width adaptation - Master: 64b
    // Connected to slaves with widths: [64]
    // ================================================================

    // Per-width path-active gates (see comment in adapter_generator.py).
    logic aw_gate_ok;
    logic ar_gate_ok;
    logic aw_path_active_64b;
    assign aw_path_active_64b = (comb_slave_select_aw[0] | comb_slave_select_aw[1] | comb_slave_select_aw[2]) && aw_gate_ok;
    logic w_path_active_64b;
    assign w_path_active_64b = w_slave_select[0] | w_slave_select[1] | w_slave_select[2];
    logic ar_path_active_64b;
    assign ar_path_active_64b = (comb_slave_select_ar[0] | comb_slave_select_ar[1] | comb_slave_select_ar[2]) && ar_gate_ok;
    logic b_path_active_64b;
    assign b_path_active_64b = b_slave_select[0] | b_slave_select[1] | b_slave_select[2];
    logic r_path_active_64b;
    assign r_path_active_64b = r_slave_select[0] | r_slave_select[1] | r_slave_select[2];

    // ================================================================
    // Direct passthrough: 64b → 64b (no converter)
    // Requests: fub_axi_* → dma_64b_*
    // Responses: dma_64b_* → MUX → fub_axi_*
    // ================================================================

    // AW channel (request: fub → output)
    assign dma_64b_aw.id     = xbar_axi_awid;
    assign dma_64b_aw.addr   = fub_axi_awaddr;
    assign dma_64b_aw.len    = fub_axi_awlen;
    assign dma_64b_aw.size   = fub_axi_awsize;
    assign dma_64b_aw.burst  = fub_axi_awburst;
    assign dma_64b_aw.lock   = fub_axi_awlock;
    assign dma_64b_aw.cache  = fub_axi_awcache;
    assign dma_64b_aw.prot   = fub_axi_awprot;
    assign dma_64b_aw.qos    = fub_axi_awqos;
    assign dma_64b_aw.region = fub_axi_awregion;
    assign dma_64b_aw.user   = fub_axi_awuser;
    assign dma_64b_awvalid   = fub_axi_awvalid && aw_path_active_64b;
    // awready routed via MUX

    // W channel (request: fub → output)
    assign dma_64b_w.data  = fub_axi_wdata;
    assign dma_64b_w.strb  = fub_axi_wstrb;
    assign dma_64b_w.last  = fub_axi_wlast;
    assign dma_64b_w.user  = fub_axi_wuser;
    assign dma_64b_wvalid  = fub_axi_wvalid && w_path_active_64b;
    // wready routed via MUX

    // B channel (response: output → MUX → fub)
    // Ready gated by the response head — see b_path_active comment.
    assign dma_64b_bready = fub_axi_bready && b_path_active_64b;
    // bid, bresp, bvalid routed via MUX (user field ignored)

    // AR channel (request: fub → output)
    assign dma_64b_ar.id     = xbar_axi_arid;
    assign dma_64b_ar.addr   = fub_axi_araddr;
    assign dma_64b_ar.len    = fub_axi_arlen;
    assign dma_64b_ar.size   = fub_axi_arsize;
    assign dma_64b_ar.burst  = fub_axi_arburst;
    assign dma_64b_ar.lock   = fub_axi_arlock;
    assign dma_64b_ar.cache  = fub_axi_arcache;
    assign dma_64b_ar.prot   = fub_axi_arprot;
    assign dma_64b_ar.qos    = fub_axi_arqos;
    assign dma_64b_ar.region = fub_axi_arregion;
    assign dma_64b_ar.user   = fub_axi_aruser;
    assign dma_64b_arvalid   = fub_axi_arvalid && ar_path_active_64b;
    // arready routed via MUX

    // R channel (response: output → MUX → fub)
    // Ready gated by the response head — see r_path_active comment.
    assign dma_64b_rready = fub_axi_rready && r_path_active_64b;
    // rid, rdata, rresp, rlast, rvalid routed via MUX (user field ignored)

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    // -------- AW->B slave_select tracking FIFO --------
    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    logic [NUM_SLAVES-1:0] aw_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] aw_trk_wptr, aw_trk_rptr;
    logic aw_trk_push, aw_trk_pop;

    assign aw_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_trk_pop  = fub_axi_bvalid && fub_axi_bready;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            aw_trk_wptr <= '0;
            aw_trk_rptr <= '0;
        end else begin
            if (aw_trk_push) begin
                aw_trk_mem[aw_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                aw_trk_wptr <= aw_trk_wptr + 1'b1;
            end
            if (aw_trk_pop) begin
                aw_trk_rptr <= aw_trk_rptr + 1'b1;
            end
        end
    )

    assign b_slave_select = (aw_trk_wptr != aw_trk_rptr)
                          ? aw_trk_mem[aw_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // Single-outstanding-target (writes): only accept a new AW
    // while every outstanding write targets the SAME slave. The
    // B response mux replays responses in AW issue order; slaves
    // respond in their own accept order, so cross-slave outstanding
    // writes from several masters can deadlock the heads against
    // each other. Same-slave pipelining is unaffected.
    logic [NUM_SLAVES-1:0] r_aw_active_target;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_aw_active_target <= '0;
        end else if (aw_trk_push) begin
            r_aw_active_target <= comb_slave_select_aw;
        end
    )
    logic aw_trk_full;
    assign aw_trk_full = (aw_trk_wptr[AW_TRK_AW] != aw_trk_rptr[AW_TRK_AW]) &&
                         (aw_trk_wptr[AW_TRK_AW-1:0] == aw_trk_rptr[AW_TRK_AW-1:0]);
    assign aw_gate_ok = ((aw_trk_wptr == aw_trk_rptr) ||
                         (comb_slave_select_aw == r_aw_active_target)) &&
                        !aw_trk_full;

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // OUTPUT slave_select_ar mirrors the live combinational decode.
    assign slave_select_ar = comb_slave_select_ar;

    // -------- AR->R slave_select tracking FIFO --------
    localparam int AR_TRK_DEPTH = 16;
    localparam int AR_TRK_AW    = 4;
    logic [NUM_SLAVES-1:0] ar_trk_mem [AR_TRK_DEPTH];
    logic [AR_TRK_AW:0] ar_trk_wptr, ar_trk_rptr;
    logic ar_trk_push, ar_trk_pop;

    assign ar_trk_push = fub_axi_arvalid && fub_axi_arready;
    assign ar_trk_pop  = fub_axi_rvalid && fub_axi_rready && fub_axi_rlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ar_trk_wptr <= '0;
            ar_trk_rptr <= '0;
        end else begin
            if (ar_trk_push) begin
                ar_trk_mem[ar_trk_wptr[AR_TRK_AW-1:0]] <= comb_slave_select_ar;
                ar_trk_wptr <= ar_trk_wptr + 1'b1;
            end
            if (ar_trk_pop) begin
                ar_trk_rptr <= ar_trk_rptr + 1'b1;
            end
        end
    )

    assign r_slave_select = (ar_trk_wptr != ar_trk_rptr)
                          ? ar_trk_mem[ar_trk_rptr[AR_TRK_AW-1:0]]
                          : '0;

    // Single-outstanding-target (reads) — see aw_gate_ok comment.
    logic [NUM_SLAVES-1:0] r_ar_active_target;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_ar_active_target <= '0;
        end else if (ar_trk_push) begin
            r_ar_active_target <= comb_slave_select_ar;
        end
    )
    logic ar_trk_full;
    assign ar_trk_full = (ar_trk_wptr[AR_TRK_AW] != ar_trk_rptr[AR_TRK_AW]) &&
                         (ar_trk_wptr[AR_TRK_AW-1:0] == ar_trk_rptr[AR_TRK_AW-1:0]);
    assign ar_gate_ok = ((ar_trk_wptr == ar_trk_rptr) ||
                         (comb_slave_select_ar == r_ar_active_target)) &&
                        !ar_trk_full;

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            3'b001: begin  // Slave 0 (64b)
                fub_axi_awready = dma_64b_awready;
            end
            3'b010: begin  // Slave 1 (64b)
                fub_axi_awready = dma_64b_awready;
            end
            3'b100: begin  // Slave 2 (64b)
                fub_axi_awready = dma_64b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Single-outstanding-target: hold off a new AW while writes
        // to a different slave are in flight (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            3'b001: begin  // Slave 0 (64b)
                fub_axi_wready = dma_64b_wready;
            end
            3'b010: begin  // Slave 1 (64b)
                fub_axi_wready = dma_64b_wready;
            end
            3'b100: begin  // Slave 2 (64b)
                fub_axi_wready = dma_64b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    always_comb begin
        fub_axi_bid = 4'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;

        case (b_slave_select)
            3'b001: begin  // Slave 0 (64b)
                fub_axi_bid = dma_64b_b.id[3:0];
                fub_axi_bresp = dma_64b_b.resp;
                fub_axi_bvalid = dma_64b_bvalid;
            end
            3'b010: begin  // Slave 1 (64b)
                fub_axi_bid = dma_64b_b.id[3:0];
                fub_axi_bresp = dma_64b_b.resp;
                fub_axi_bvalid = dma_64b_bvalid;
            end
            3'b100: begin  // Slave 2 (64b)
                fub_axi_bid = dma_64b_b.id[3:0];
                fub_axi_bresp = dma_64b_b.resp;
                fub_axi_bvalid = dma_64b_bvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

    // AR-ready MUX (request side: uses combinational comb_slave_select_ar)
    always_comb begin
        fub_axi_arready = 1'b0;
        case (comb_slave_select_ar)
            3'b001: begin  // Slave 0 (64b)
                fub_axi_arready = dma_64b_arready;
            end
            3'b010: begin  // Slave 1 (64b)
                fub_axi_arready = dma_64b_arready;
            end
            3'b100: begin  // Slave 2 (64b)
                fub_axi_arready = dma_64b_arready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Single-outstanding-target: hold off a new AR while reads
        // to a different slave are in flight (see ar_gate_ok).
        if (!ar_gate_ok) fub_axi_arready = 1'b0;
    end

    // Read response MUX (R channel - uses r_slave_select FIFO head)
    always_comb begin
        fub_axi_rid = 4'd0;
        fub_axi_rdata = 64'd0;
        fub_axi_rresp = 2'b00;
        fub_axi_rlast = 1'b0;
        fub_axi_rvalid = 1'b0;

        case (r_slave_select)
            3'b001: begin  // Slave 0 (64b)
                fub_axi_rid = dma_64b_r.id[3:0];
                fub_axi_rdata = dma_64b_r.data;
                fub_axi_rresp = dma_64b_r.resp;
                fub_axi_rlast = dma_64b_r.last;
                fub_axi_rvalid = dma_64b_rvalid;
            end
            3'b010: begin  // Slave 1 (64b)
                fub_axi_rid = dma_64b_r.id[3:0];
                fub_axi_rdata = dma_64b_r.data;
                fub_axi_rresp = dma_64b_r.resp;
                fub_axi_rlast = dma_64b_r.last;
                fub_axi_rvalid = dma_64b_rvalid;
            end
            3'b100: begin  // Slave 2 (64b)
                fub_axi_rid = dma_64b_r.id[3:0];
                fub_axi_rdata = dma_64b_r.data;
                fub_axi_rresp = dma_64b_r.resp;
                fub_axi_rlast = dma_64b_r.last;
                fub_axi_rvalid = dma_64b_rvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

endmodule : dma_adapter
